#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
# Render-table translation of render.c, copyright Charles MacDonald and contributors.
# Contains no former CPU tables or CPU table generator.

def generate_render_tables():
    """Generate lut[65536] (uint8) and bp_lut[65536] (uint32 LE)."""
    lut = bytearray(0x10000)

    for bx in range(0x100):
        for sx in range(0x100):
            b  = bx & 0x0F
            bp = 1 if (bx & 0x20) else 0
            bf = bx & 0x7F
            s  = sx & 0x0F
            sf = (sx & 0x0F) | 0x10 | 0x40

            if bx & 0x40:
                c = bf
            else:
                if bp:
                    if b:
                        c = bf | 0x40
                    else:
                        c = sf if s else bf
                else:
                    c = sf if s else bf

            lut[(bx << 8) | sx] = c & 0xFF

    # Bitplane to packed pixel LUT (little-endian)
    bp_lut = [0] * 0x10000

    for i in range(0x100):
        for j in range(0x100):
            out = 0
            for x in range(8):
                if j & (0x80 >> x):
                    out |= 8 << (x << 2)
                if i & (0x80 >> x):
                    out |= 4 << (x << 2)
            # Little endian indexing: _bp_lut[(j << 8) | (i)] = out
            bp_lut[(j << 8) | i] = out & 0xFFFFFFFF

    return bytes(lut), bp_lut


def write_hex_array_u8(f, name, data, per_line=16):
    """Write a uint8 array as hex."""
    f.write(f"static const uint8_t {name}[{len(data)}] = {{\n")
    for i in range(0, len(data), per_line):
        chunk = data[i:i+per_line]
        vals = ", ".join(f"0x{b:02X}" for b in chunk)
        comma = "," if i + per_line < len(data) else ""
        f.write(f"    {vals}{comma}\n")
    f.write("};\n")


def write_hex_array_u32(f, name, data, per_line=8):
    """Write a uint32 array as hex."""
    f.write(f"static const uint32_t {name}[{len(data)}] = {{\n")
    for i in range(0, len(data), per_line):
        chunk = data[i:i+per_line]
        vals = ", ".join(f"0x{v:08X}" for v in chunk)
        comma = "," if i + per_line < len(data) else ""
        f.write(f"    {vals}{comma}\n")
    f.write("};\n")


def main():
    lut, bp_lut = generate_render_tables()
    render_path = "smsplus_render_tables.h"
    with open(render_path, "w") as f:
        f.write("/* Auto-generated by generate_tables.py — DO NOT EDIT */\n")
        f.write("#ifndef SMSPLUS_RENDER_TABLES_H\n")
        f.write("#define SMSPLUS_RENDER_TABLES_H\n\n")
        f.write("#include <stdint.h>\n\n")
        write_hex_array_u8(f, "smsplus_lut", lut)
        f.write("\n")
        write_hex_array_u32(f, "smsplus_bp_lut", bp_lut)
        f.write("\n#endif /* SMSPLUS_RENDER_TABLES_H */\n")
    print(f"  Wrote {render_path}")

    print("Done!")


if __name__ == "__main__":
    main()
